import { handler as render } from './dist/server/entry.mjs';
import express from 'express';

const app = express();

// Serve the static assets generated by Astro
app.use(express.static('./dist/client'));

// Route all other requests to Astro's SSR handler
app.use((req, res) => {
    render(req, res);
});

// Use cPanel's dynamic passenger port, or fallback to 3000
const port = process.env.PORT || 3000;
app.listen(port, () => {
    console.log(`Astro SSR running on port ${port}`);
});
